.lc-vinyl-deck-root {
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  color: var(--lc-ink);
  font-family: inherit;
  width: min(100%, 320px);
  padding: 24px;
  background: var(--lc-surface);
  border-top-width: 1px;
  border-top-style: solid;
  border-top-color: #a79c8d;
  border-right-width: 1px;
  border-right-style: solid;
  border-right-color: #a79c8d;
  border-bottom-width: 1px;
  border-bottom-style: solid;
  border-bottom-color: #a79c8d;
  border-left-width: 1px;
  border-left-style: solid;
  border-left-color: #a79c8d;
  border-radius: 12px;
  box-shadow: 0 8px 0 #afa18f;
}
.lc-vinyl-deck-title {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin-bottom: 20px;
  font-size: 17px;
  font-family: Georgia, serif;
}
.lc-vinyl-deck-platter {
  position: relative;
  padding: 12px 20px 12px 0;
}
.lc-vinyl-deck-record {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 220px;
  max-width: 100%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: repeating-radial-gradient(circle, #111111 0px, #111111 2px, #292929 3px, #111111 4px);
  box-shadow: 3px 8px 14px #00000035;
}
.lc-vinyl-deck-recordlabel {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 78px;
  height: 78px;
  border-radius: 50%;
  background: var(--lc-accent);
  font: 10px monospace;
  color: #211b14;
}
.lc-vinyl-deck-hole {
  width: 8px;
  height: 8px;
  background: #26211a;
  border-radius: 50%;
}
.lc-vinyl-deck-arm {
  position: absolute;
  right: 18px;
  top: 0;
  width: 8px;
  height: 155px;
  background: linear-gradient(90deg, #988d7f, #f0ece3, #9c9183);
  border-radius: 6px;
  transform-origin: top;
  transform: rotate(-12deg);
  box-shadow: 2px 3px 4px #00000030;
}
.lc-vinyl-deck-head {
  position: absolute;
  bottom: -8px;
  left: -7px;
  width: 22px;
  height: 34px;
  background: #4b443b;
  border-radius: 4px;
}
.lc-vinyl-deck-control {
  box-sizing: border-box;
  min-height: 44px;
  font-family: inherit;
  cursor: pointer;
  color: var(--lc-ink);
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  margin-top: 20px;
  padding: 8px 0;
  border-top-width: 1px;
  border-top-style: solid;
  border-top-color: #afa393;
  border-right-width: 0;
  border-right-style: undefined;
  border-right-color:;
  border-bottom-width: 0;
  border-bottom-style: undefined;
  border-bottom-color:;
  border-left-width: 0;
  border-left-style: undefined;
  border-left-color:;
  background: transparent;
  font: 12px monospace;
}
.lc-vinyl-deck-control:focus-visible {
  outline: 2px solid var(--lc-accent);
  outline-offset: 4px;
}

'use client';
import { useState, useRef, useSyncExternalStore } from 'react';
import type { CSSProperties } from 'react';
import { motion, useInView } from 'motion/react';
import './VinylDeck.css';
const c = {
  root: 'lc-vinyl-deck-root',
  title: 'lc-vinyl-deck-title',
  platter: 'lc-vinyl-deck-platter',
  record: 'lc-vinyl-deck-record',
  recordlabel: 'lc-vinyl-deck-recordlabel',
  hole: 'lc-vinyl-deck-hole',
  arm: 'lc-vinyl-deck-arm',
  head: 'lc-vinyl-deck-head',
  control: 'lc-vinyl-deck-control'
};

export interface VinylDeckProps {
  title?: string;
  artist?: string;
  spinning?: boolean;
  defaultSpinning?: boolean;
  onChange?: (spinning: boolean) => void;
  rpm?: number;
  accent?: string;
  surface?: string;
  ink?: string;
  className?: string;
}

const motionQuery = '(prefers-reduced-motion: reduce)';
const motionSnapshot = () => typeof window !== 'undefined' && window.matchMedia(motionQuery).matches;
const motionSubscribe = (listener: () => void) => {
  const media = window.matchMedia(motionQuery);
  media.addEventListener('change', listener);
  return () => media.removeEventListener('change', listener);
};
function useMotionPreference() {
  return useSyncExternalStore(motionSubscribe, motionSnapshot, () => false);
}

export default function VinylDeck({
  title = 'Slow Sunday',
  artist = 'Side A / Studio Sessions',
  spinning,
  defaultSpinning = false,
  onChange,
  rpm = 33,
  accent = '#e67846',
  surface = '#e6dfd3',
  ink = '#302a24',
  className = ''
}: VinylDeckProps) {
  const reduce = useMotionPreference();
  const ref = useRef<HTMLDivElement>(null);
  const near = useInView(ref);
  const [inner, setInner] = useState(defaultSpinning);
  const on = spinning ?? inner;
  return (
    <div
      className={[c.root, className].filter(Boolean).join(' ')}
      style={{ '--lc-accent': accent, '--lc-surface': surface, '--lc-ink': ink } as CSSProperties}
      ref={ref}
    >
      <div className={c.title}>
        <strong>{title}</strong>
        <span>{artist}</span>
      </div>
      <div className={c.platter}>
        <motion.div
          className={c.record}
          aria-hidden="true"
          animate={{ rotate: on && !reduce && near ? 360 : 0 }}
          transition={
            on && !reduce && near
              ? { duration: 60 / Math.max(1, rpm), repeat: Infinity, ease: 'linear' }
              : { duration: 0 }
          }
        >
          <span className={c.recordlabel}>
            <span>SIDE A</span>
            <strong>LP / 33</strong>
            <i className={c.hole} />
          </span>
        </motion.div>
        <motion.div
          aria-hidden="true"
          className={c.arm}
          animate={{ rotate: on ? 20 : 0 }}
          transition={reduce ? { duration: 0 } : { type: 'spring', stiffness: 90, damping: 18 }}
        >
          <span className={c.head} />
        </motion.div>
      </div>
      <button
        type="button"
        aria-pressed={on}
        className={c.control}
        onClick={() => {
          if (spinning === undefined) setInner(!on);
          onChange?.(!on);
        }}
      >
        {on ? 'Stop rotation' : 'Spin the record'}
        <span aria-hidden="true">{on ? 'Ⅱ' : '▶'}</span>
      </button>
    </div>
  );
}
